        elif format[i:i+2] == '}}':
            i += 2
            continue
        elif format[i] == '{':
            # Check if there's a matching }
            j = format.find('}', i + 1)
            if j == -1:
                raise ValueError("unmatched '{' in format string")
            # Check for nested braces inside the field
            inner = format[i+1:j]
            if '{' in inner or '}' in inner:
                raise ValueError("braces not fully enclosed within matching braces")
            i = j + 1
        elif format[i] == '}':
